component_data_script:
def norm(value):
	key = str(value or "").strip().lower()
	if key in ["you", "me", "personal", "people", "for you"]:
		return "personal"
	if key in ["business", "company", "companies", "for your business"]:
		return "business"
	return "both"


def tag_of(aud):
	if aud == "personal":
		return "For you"
	if aud == "business":
		return "For your business"
	return ""


def read_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [line for line in raw.split("\n") if line.strip()]
	if not isinstance(raw, list):
		return []
	return [str(line) for line in raw if str(line).strip()]


def split_row(line, size):
	parts = [part.strip() for part in str(line).split("|")]
	while len(parts) < size:
		parts.append("")
	return parts

def money(amount):
	digits = str(int(amount))
	out = ""
	while len(digits) > 3:
		out = "," + digits[-3:] + out
		digits = digits[:-3]
	return digits + out


base_opts = []
add_opts = []
currency = "£"
book_href = "consultation"
first_total = 0
try:
	currency = str(props.get("currency") or "£").strip() or "£"
	book_href = str(props.get("book_href") or "consultation").strip() or "consultation"
	first_found = False
	for line in read_rows(props.get("options")):
		parts = split_row(line, 4)
		try:
			amount = int(float(str(parts[3]).replace(",", "").replace(currency, "").strip()))
		except Exception:
			continue
		if not parts[2]:
			continue
		aud = norm(parts[0])
		# two flags, because a bound attribute always renders: the row shows the input that
		# carries `checked` only when it is the picked one, so the page is right without script
		record = {"aud": aud, "tag": tag_of(aud), "label": parts[2], "amount": str(amount), "price_label": currency + money(amount), "checked": "", "unchecked": "1"}
		if parts[1].strip().lower() == "add":
			add_opts.append(record)
		else:
			if not first_found and aud in ["personal", "both"]:
				record["checked"] = "1"
				record["unchecked"] = ""
				first_found = True
				first_total = amount
			base_opts.append(record)
	if not first_found and base_opts:
		base_opts[0]["checked"] = "1"
		base_opts[0]["unchecked"] = ""
		first_total = int(base_opts[0]["amount"])
except Exception:
	base_opts = []
	add_opts = []
component.base_opts = base_opts
component.add_opts = add_opts
component.default_total = currency + money(first_total)
component.default_month = "or " + currency + money(round(first_total / 12.0)) + " a month by direct debit"
component.book_link = book_href + "?estimate=" + str(first_total) + ("" if currency == "£" else "&currency=" + currency)
component.component_data = {"currency": currency, "book_href": book_href}
